def interleaveCharacters(word1, word2, target):
    MOD = 10**9 + 7
    a = len(word1)
    b = len(word2)

    # f[i][j]: ways so far with last used index i in word1 and j in word2 (0 = none yet)
    f = [[0] * (b + 1) for _ in range(a + 1)]
    f[0][0] = 1

    for c in target:
        g = [[0] * (b + 1) for _ in range(a + 1)]

        # Place c using word1 at index i: sum over all smaller previous indices i' < i
        for j in range(b + 1):
            running = 0
            for i in range(1, a + 1):
                running += f[i - 1][j]
                if word1[i - 1] == c:
                    g[i][j] = (g[i][j] + running) % MOD

        # Place c using word2 at index j: sum over all smaller previous indices j' < j
        for i in range(a + 1):
            running = 0
            for j in range(1, b + 1):
                running += f[i][j - 1]
                if word2[j - 1] == c:
                    g[i][j] = (g[i][j] + running) % MOD

        f = g

    # Require at least one character from each word: skip the i = 0 row and j = 0 column
    total = 0
    for i in range(1, a + 1):
        for j in range(1, b + 1):
            total += f[i][j]
    return total % MOD
